export default function nextServer({ values, previousState }) {
  if (!Array.isArray(values)) throw Error("Invalid server sheet");
  const idx = previousState?.index ?? 0;
  if (!Number.isInteger(idx) || idx < 0) throw Error("Invalid monitor state");
  if (values.length === 0)
    return { state: { index: 0 }, more: false, url: "http://unused.invalid", server: "", count: 0 };
  const header = values[0];
  if (!Array.isArray(header) || header.filter((v) => v === "Server").length !== 1)
    throw Error("Server_List needs one Server header");
  const column = header.indexOf("Server");
  const rows = values
    .slice(1)
    .filter((r) => Array.isArray(r) && r.some((v) => v !== "" && v !== null));
  if (idx >= rows.length)
    return {
      state: { index: idx },
      more: false,
      url: "http://unused.invalid",
      server: "",
      count: idx,
    };
  const server = rows[idx][column];
  if (typeof server !== "string" || !server.trim() || /[\r\n]/.test(server))
    throw Error("Every server row needs a server address");
  return { state: { index: idx + 1 }, more: true, url: "http://" + server, server, count: idx + 1 };
}

