export default function assessServer({ url, index, status, headers, previousState }) {
  const prior = previousState?.index === index ? previousState.hops : 0;
  if (!Number.isInteger(prior) || prior < 0) throw Error("Invalid redirect state");
  if (status >= 300 && status < 400 && typeof headers?.location === "string" && headers.location) {
    if (prior >= 21)
      return { state: { index, hops: prior, nextUrl: "" }, redirect: false, alive: false };
    try {
      const target = new URL(headers.location, url);
      if (!["http:", "https:"].includes(target.protocol) || target.username || target.password)
        throw Error();
      return {
        state: { index, hops: prior + 1, nextUrl: target.toString() },
        redirect: true,
        alive: false,
      };
    } catch {
      return { state: { index, hops: prior, nextUrl: "" }, redirect: false, alive: false };
    }
  }
  return {
    state: { index, hops: prior, nextUrl: "" },
    redirect: false,
    alive: status >= 200 && status < 300,
  };
}

