export default function serverFields({ server, status }) {
  if (typeof server !== "string" || !server || !["Alive", "Down"].includes(status))
    throw Error("Invalid server or status");
  const now = new Date().toISOString(),
    day = now.slice(0, 10),
    stamp = now.slice(0, 19).replace("T", " ");
  return {
    values: [[server, status === "Alive" ? day : stamp, status]],
    subject: "🔻 Server Down: " + server + ": " + day,
    message:
      "Hi Team,\n\nAt " +
      stamp +
      ", the following server failed its HTTP check:\n\n🔻 Server Down: " +
      server +
      "\n\nPlease investigate immediately to prevent service disruption.\n\nAutomated Monitoring System\n",
  };
}

